1|// Reader model: the slim shape the client receives. Joins paragraphs to
2|// scenes by ordinal range in reading order; analysis internals never leave.
3|import type { AnalyzedScene, Book } from "./types";
4|import type { Vector8 } from "./types";
5|
6|export interface ReaderParagraph {
7|  id: string;
8|  n: number;
9|  text: string;
10|}
11|
12|export interface ReaderScene {
13|  id: string;
14|  title: string;
15|  emotion: { vector: Vector8; intensity: number; tempo: number } | null;
16|  paragraphs: ReaderParagraph[];
17|}
18|
19|export interface ReaderChapter {
20|  ch: number;
21|  title: string;
22|  scenes: ReaderScene[];
23|}
24|
25|export interface ReaderModel {
26|  bookId: string;
27|  textVersion: string;
28|  title: string;
29|  author: string;
30|  chapters: ReaderChapter[];
31|}
32|
33|// Throws on unordered scenes and on paragraphs covered zero or two times.
34|export function buildReaderModel(
35|  book: Pick<Book, "id" | "title" | "author" | "chapters" | "paragraphs" | "textVersion">,
36|  analysis: { scenes: AnalyzedScene[] },
37|): ReaderModel {
38|  const byN = new Map(book.paragraphs.map((p) => [p.n, p]));
39|  const scenes = [...analysis.scenes];
40|  for (let i = 1; i < scenes.length; i++) {
41|    const prev = scenes[i - 1];
42|    const cur = scenes[i];
43|    if (prev && cur && (cur.start_n < prev.start_n || (cur.start_n === prev.start_n && cur.end_n < prev.end_n))) {
44|      throw new Error(`scenes out of order at ${cur.id}`);
45|    }
46|  }
47|  const seen = new Set<number>();
48|  const sceneParagraphs = new Map<string, ReaderParagraph[]>();
49|  for (const scene of scenes) {
50|    const paras: ReaderParagraph[] = [];
51|    for (let n = scene.start_n; n <= scene.end_n; n++) {
52|      const p = byN.get(n);
53|      if (!p) throw new Error(`scene ${scene.id} covers missing ordinal ${n}`);
54|      if (seen.has(n)) throw new Error(`ordinal ${n} covered twice`);
55|      seen.add(n);
56|      paras.push({ id: p.id, n: p.n, text: p.text });
57|    }
58|    sceneParagraphs.set(scene.id, paras);
59|  }
60|  if (seen.size !== book.paragraphs.length) {
61|    throw new Error(`coverage gap: ${book.paragraphs.length - seen.size} paragraphs uncovered`);
62|  }
63|  const chapters: ReaderChapter[] = book.chapters.map((chapter) => {
64|    const mine = scenes.filter((s) => s.ch === chapter.ch);
65|    if (mine.some((s) => s.start_n < chapter.start_n || s.end_n > chapter.end_n)) {
66|      throw new Error(`a scene crosses chapter ${chapter.ch} bounds`);
67|    }
68|    return {
69|      ch: chapter.ch,
70|      title: chapter.title,
71|      scenes: mine.map((s) => ({
72|        id: s.id,
73|        title: s.title,
74|        emotion: s.final === null ? null : { ...s.final },
75|        paragraphs: sceneParagraphs.get(s.id) ?? [],
76|      })),
77|    };
78|  });
79|  return {
80|    bookId: book.id,
81|    textVersion: book.textVersion,
82|    title: book.title,
83|    author: book.author,
84|    chapters,
85|  };
86|}

